command:
// Party Resource Report
// Author: Evounnamed
// v1.0
// Description: This macro enables the user to select a party OR single OR multiple 
// tokens to perform a light/food Resource Report from the chosen actor's inventory.
// -----------------------------------------------

function getActivePartyCharacters() {
    return game.users
        .filter(user => user.active && user.character) // Only active users with assigned characters
        .map(user => user.character);
}

function generateResourceReport(actors) {
    let lightContent = `<p style="text-align:center; font-size:20px; font-family:'JSL Blackletter', Georgia, serif;">Light Sources</p><ul>`;
    let foodContent = `<p style="text-align:center; font-size:20px; font-family:'JSL Blackletter', Georgia, serif;">Food Sources</p><ul>`;
    let totalTorches = 0;
    let totalOilFlasks = 0;
    let totalRations = 0;

    actors.forEach(actor => {
        const resources = { "Torch": 0, "Oil, Flask": 0, "Rations": 0 };
        actor.items.forEach(item => {
            if (["Torch", "Oil, Flask", "Rations"].includes(item.name)) {
                resources[item.name] += item.system.quantity || 0;
            }
        });

        lightContent += `<li><strong>${actor.name}:</strong> Torches: ${resources["Torch"]}, Oil Flasks: ${resources["Oil, Flask"]}</li>`;
        foodContent += `<li><strong>${actor.name}:</strong> Rations: ${resources["Rations"]}</li>`;

        totalTorches += resources["Torch"];
        totalOilFlasks += resources["Oil, Flask"];
        totalRations += resources["Rations"];
    });

    lightContent += `</ul><p><strong>Total Torches: ${totalTorches}</strong></p><p><strong>Total Oil Flasks: ${totalOilFlasks}</strong></p>`;
    foodContent += `</ul><p><strong>Total Rations: ${totalRations}</strong></p>`;

    return `<p style="text-align:center; color:#990000; font-size:24px; font-family:'JSL Blackletter', Georgia, serif;">Resource Report</p><hr style="margin: 5px 0;">` + lightContent + `<hr style="margin-top: 10px; margin-bottom: 10px;">` + foodContent;
}

new Dialog({
    title: "Resource Report Options",
    content: `
        <p style="font-size:16px; text-align:center;">Choose how to run the Resource Report:</p>
        <div style="text-align:center; margin-top:10px;">
            <button id="party-report" style="padding: 10px 20px; margin-bottom: 10px; font-size:18px; font-family:'JSL Blackletter', Georgia, serif; background-color: #990000; color: white; border: none; border-radius: 5px; cursor: pointer;">Current Party</button>
            <button id="selected-report" style="padding: 10px 20px; margin-bottom: 10px; font-size:18px; font-family:'JSL Blackletter', Georgia, serif; background-color: #990000; color: white; border: none; border-radius: 5px; cursor: pointer;">Selected Tokens</button>
        </div>
    `,
    buttons: {},
    render: html => {
        html.find('#party-report').click(() => {
            const partyActors = getActivePartyCharacters();
            if (partyActors.length === 0) {
                ui.notifications.warn("No active players with assigned characters found.");
                return;
            }
            const chatContent = generateResourceReport(partyActors);
            ChatMessage.create({
                user: game.user.id,
                speaker: { alias: game.user.name },
                content: chatContent
            });
        });

        html.find('#selected-report').click(() => {
            const selectedTokens = canvas.tokens.controlled;
            if (selectedTokens.length === 0) {
                ui.notifications.warn("Please select at least one token.");
                return;
            }
            const actors = selectedTokens.map(token => token.actor);
            const chatContent = generateResourceReport(actors);
            ChatMessage.create({
                user: game.user.id,
                speaker: { alias: game.user.name },
                content: chatContent
            });
        });
    }
}).render(true);
